def-hyp(
    list-partial(
        Type.annotation(@n, Nat),
        Type.annotation(@x_n, Type.to(Nat, S@Topology.ctxt.S)),
        Type.annotation(@x, S@Topology.ctxt.S)
    ),
    Topology.seqLimit(n, x_n, x),
    Logic.forall-typed(
        @U,
        Set(S@Topology.ctxt.S),
        Logic.implies(
            Topology.neighborhood(U, x),
            Logic.exists-typed(
                @N,
                Nat,
                Logic.forall-typed(
                    @k,
                    Nat,
                    Logic.implies(Le(N, k), Set.mem(Type.apply(x_n, n), U))
                )
            )
        )
    )
)
